css:
@media print {
     @page {
        margin-left: 1in;
        margin-right: 1in;
        margin-top: 0.5mm;
        margin-bottom: 0.5mm;
      }
}

@media (max-width: 767px)
.print-format {
    padding: 0.8in;
}

html:
{% if doc.prescription_table %}
{%- for row in doc.prescription_table -%}
{% if row.dont_issue !=1 %}

<div style="max-width: 220px; max-height: 225.6px;font-size: 8px;">
 <div class="row section-break">
 <div style="text-align: center;" class="row">
 <strong style="font-size: 13.5px">{{ row.item_name|upper }} [{{ row.billed_quantity or " " }}]</strong>
 </div>
 <div style="text-align: center;" class="row">
 <strong style="font-size: 9px; color: grey;">

     <!--Check if selected items have sub_preparation_type and item route-->
     {% if row.sub_preparation_type and row.item_route %}

     <!--Checks for the route and prep_type to filter the first keyword in the label-->
     {% if "Suspension" in row.sub_preparation_type and "Oral" in row.item_route %}

        {{row.pharmacy_dose}} to be taken every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Syrups" in row.sub_preparation_type and "Oral" in row.item_route %}

        {{row.pharmacy_dose}} to be taken every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Drops" in row.sub_preparation_type and "Oral" in row.item_route %}

        {{row.pharmacy_dose}} to be administered every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Tablet" in row.sub_preparation_type or "Capsule" in row.sub_preparation_type and "Oral" in row.item_route %}

        {{row.pharmacy_dose}} to be taken every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Lozenge" in row.sub_preparation_type and "Oral" in row.item_route %}

        {{row.pharmacy_dose}} to be dissolved slowly in the mouth every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Sachets" in row.sub_preparation_type and "Oral" in row.item_route %}

        {{row.pharmacy_dose}} to be dissolved then taken every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "ORS" in row.sub_preparation_type and "Oral" in row.item_route %}

        {{row.pharmacy_dose}} to be taken on every loose motion/vomit every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Topical" in row.item_route %}

        To be applied on affected area Every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Ear Drop" in row.item_route and "Ear Drop" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be instilled in affected ear every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Ear" in row.item_route and "Ear Drop" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be instilled in affected ear every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Eye Drop" in row.item_route and "Eye Drop" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be instilled in affected eye every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Eye" in row.item_route and "Eye Drop" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be instilled in affected eye every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Eye Ointment" in row.item_route or "Eye Ointment" in row.sub_preparation_type %}

        To be applied in affected eye every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Ear Ointment" in row.item_route and "Ear Ointment" in row.sub_preparation_type %}

        To be applied in affected ear every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Eye" in row.item_route or "Eye Ointment" in row.sub_preparation_type %}

        To be applied in affected eye every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Ear" in row.item_route and "Ear Ointment" in row.sub_preparation_type %}

        To be applied in affected ear every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Per-rectal" in row.item_route and "Suppository" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be inserted rectally every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Vaginal" in row.item_route and "Pessary" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be inserted vaginally every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) AT NIGHT for {{row.pharmacy_duration}} days

     {% elif "Per-rectal" in row.item_route and "Rectal Gel" in row.sub_preparation_type or "Enema" in row.sub_preparation_type  %}  

        To be applied in affected area every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Vaginal" in row.item_route and "Cream" in row.sub_preparation_type or "Gel/Cream" in row.sub_preparation_type  %}  

        To be applied in affected area every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Intranasal" in row.item_route and "Spray" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be sprayed into the affected nostril every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Intranasal" in row.item_route and "Drop" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be Instilled into the affected nostril every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Intranasal" in row.item_route and "Vapocap" in row.sub_preparation_type %}

        Sprinkle on bedding/clothing for inhalation every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Inhalation" in row.item_route and "Vapocap" in row.sub_preparation_type %}

        Sprinkle on bedding/clothing for inhalation every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Inhalation" in row.item_route and "Inhaler" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be inhaled every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Inhalation" in row.item_route and "Turbuhaler" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be inhaled every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Inhalation" in row.item_route and "Accuhaler" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be inhaled every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Inhalation" in row.item_route and "Evohaler" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be inhaled every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Inhalation" in row.item_route and "Nebules/Respules" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be administered every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via nebulization

     {% elif "Inhalation" in row.item_route and "Nebule" in row.sub_preparation_type or "Respule" in row.sub_preparation_type %}

        {{row.pharmacy_dose}} to be administered every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via nebulization


     {% elif "Intramuscular" in row.item_route %}

        {{row.pharmacy_dose}} to be administered after every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via Intramuscular route

     {% elif "Intravenous" in row.item_route %}

        {{row.pharmacy_dose}} to be administered after every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via Intravenous route

     {% elif "Intradermal" in row.item_route %}

        {{row.pharmacy_dose}} to be administered after every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via Intradermal route

     {% elif "Subcutaneous" in row.item_route %}

        {{row.pharmacy_dose}} to be administered after every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via Subcutaneous route

     {% elif "Intrathecal" in row.item_route %}

        {{row.pharmacy_dose}} to be administered after every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via Intrathecal route

     {% elif "Infusion" in row.item_route %}

        {{row.pharmacy_dose}} to be administered every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via intravenous infusion

     {% else %}

        SOME DATA IS MISSING ON THIS ITEM TO DISPLAY THE SPECIFICS

     {% endif %}

     {% elif "Topical" in row.item_route %}

        To be applied on affected area Every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days

     {% elif "Intramuscular" in row.item_route %}

        {{row.pharmacy_dose}} to be administered after every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via Intramuscular route

     {% elif "Intravenous" in row.item_route %}

        {{row.pharmacy_dose}} to be administered after every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via Intravenous route

     {% elif "Intradermal" in row.item_route %}

        {{row.pharmacy_dose}} to be administered after every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via Intradermal route

     {% elif "Subcutaneous" in row.item_route %}

        {{row.pharmacy_dose}} to be administered after every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via Subcutaneous route

     {% elif "Intrathecal" in row.item_route %}

        {{row.pharmacy_dose}} to be administered after every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via Intrathecal route

     {% elif "Infusion" in row.item_route %}

        {{row.pharmacy_dose}} to be administered every {{24//(row.pharmacy_frequency|int)}} hours ({{row.pharmacy_frequency}} times a day) for {{row.pharmacy_duration}} days via intravenous infusion

     {% endif %}

      <br>


     </strong>

    {% if row.pharmacy_remark %}

     {{row.pharmacy_remark or " " }}  
     <br />
    {% endif %}

 {% if row.additional_item_info == "1" or row.additional_item_info == "0" %}

 {% else %}

    <span style="font-size: 8px; line-height: 20px; ">{{row.additional_item_info|lower or " "}}</span>

 {% endif %}
 </div>

 <div style=" display: flex;
 flex-direction: row;
 justify-content: space-around;
 align-items: flex-end; text-align:center;">
 <div >
 <strong>{{doc.patient|upper}}</strong>
 <p>
 Date: <strong>{{doc.encounter_date}} {{doc.encounter_time}}</strong>
 </p>
 </div>
 <div >
 <p>DOB: <strong>{{doc.patient_dob}}</strong></p>
 <p>UHID: <strong>{{doc.patient_uhid}} </strong></p>
 </div>
 </div>
 <div style="text-align: center ;">
 <strong style="line-height: 150%">GERTRUDE'S CHILDREN'S HOSPITAL</strong>
 <div style=" display: flex;
 flex-direction: row;
 justify-content: space-around;
 align-items: flex-end;">
 <strong style="font-size: 7.5px">www.gerties.org</strong>
 <strong style="font-size: 7px">Tel : 0708-988-400</strong>  
 </div>
 </div>
 </div>
</div>


<div class="page-break"></div>
{% endif %}
{%- endfor -%}
{%- endif -%}
